INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(19801, 'Ezekiel 20:21', 'Ezekiel', 20, 21, '&nbsp;خو د هغوئ اولاد زما خلاف سرکشى وکړه، او هغوئ زما د سبت سپکاوے وکړو. هغوئ زما د حکمونو پيروى ونۀ کړه، او زما د قانون په ساتلو يې غور ونۀ کړو. چا چې د دې تابعدارى وکړه نو په دې به ژوندى پاتې شى. بيا ما وفرمائيل چې، زۀ به په هغوئ خپل قهر نازل کړم او خپله غصه به په هغوئ په صحرا کښې سړه کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19802, 'Ezekiel 20:22', 'Ezekiel', 20, 22, '&nbsp;خو ما خپل لاس ترې ونيولو، بلکې د خپل نوم د خاطره ما هغه څۀ وکړل څۀ چې به هغه د هغه قومونو د سترګو د وړاندې د سپکوالى نه وساتى چا چې زۀ وليدلم چې ما هغوئ بهر راوويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19803, 'Ezekiel 20:23', 'Ezekiel', 20, 23, '&nbsp;خو ما هم په صحرا کښې دوئ سره قسم وخوړلو چې زۀ به هغوئ په نورو قومونو او مُلکونو کښې خوارۀ کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19804, 'Ezekiel 20:24', 'Ezekiel', 20, 24, '&nbsp;ځکه چې هغوئ زما قانون ونۀ منلو بلکې د منلو په ځائ يې رد کړو او زما د سبت بې‌حرمتى يې وکړه، او د هغوئ سترګې د هغوئ د پلار نيکۀ بُتانو ته وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19805, 'Ezekiel 20:25', 'Ezekiel', 20, 25, '&nbsp;ما هغوئ فضول قانون او اصُولو ته حواله کړل کوم چې د ژوند طرف ته نۀ وُو روان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19806, 'Ezekiel 20:26', 'Ezekiel', 20, 26, '&nbsp;ما هغوئ پرېښودل چې خپل ځانونه بُتانو ته په نذرانې پېش کولو سره پليت کړى تر دې چې خپل مشران زامن هم ورته قربان کړى، نو په دې کار سره به زۀ هغوئ حق حېران کړم تر دې چې هغوئ به په دې پوهه شى چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19807, 'Ezekiel 20:27', 'Ezekiel', 20, 27, '&nbsp;نو په دې وجه اے بنى آدمه، د بنى اِسرائيلو سره خبرې وکړه او هغوئ ته ووايه چې مالِک قادر مطلق خُدائ داسې فرمائى چې، هم داسې ستاسو پلار نيکۀ هم کُفر وکړو او ما سره يې غدارى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19808, 'Ezekiel 20:28', 'Ezekiel', 20, 28, '&nbsp;کله چې هغوئ ما هغه مُلک ته راوستل کوم چې ما د هغوئ سره د ورکولو وعده کړې وه نو هرکله چې به هغوئ اوچتې غونډۍ يا شنې ونې وليدلې، نو بيا به هلته هغوئ خپلې قربانۍ پېش کولې، هغوئ داسې قربانۍ بُتانو ته کولې چې زۀ يې په قهر کړم، او هغوئ هلته خپلې د خوشبويانو قربانۍ، او د څښلو نذرانې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19809, 'Ezekiel 20:29', 'Ezekiel', 20, 29, '&nbsp;ما بيا هغوئ ته وفرمائيل، نو دا کوم اوچت ځائ دے چرته چې تاسو ځئ؟ تر نن ورځې پورې ورته بامه يعنې اوچت ځائ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19810, 'Ezekiel 20:30', 'Ezekiel', 20, 30, '&nbsp;په دې وجه د بنى اِسرائيلو قوم ته ووايه، مالِک قادر مطلق خُدائ داسې فرمائى چې ولې تاسو خپل ځانونه پليتوئ لکه څنګه چې ستاسو پلار نيکۀ کړى وُو او د هغه ناپاکه بُتانو سره په زنا کولو خپل ځانونه ګمراه کوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19811, 'Ezekiel 20:31', 'Ezekiel', 20, 31, '&nbsp;کله چې تاسو خپلې نذرانې پېش کړئ او خپل زامن په اور قربانى کړئ او تاسو خپل ځانونه تر نن ورځې پورې په خپلو ټولو بُتانو پليتوئ، نو ولې زۀ تاسو، اے د بنى اِسرائيلو قومه، پرېږدم چې زما په حقله معلومات وکړئ؟ زما دې په خپل ذات قسم وى، قادر مطلق خُدائ فرمائى، زۀ به تاسو پرې نۀ ږدم چې زما معلومات وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19812, 'Ezekiel 20:32', 'Ezekiel', 20, 32, '&nbsp;تاسو وايئ چې مونږ غواړو چې د دُنيا د هغه نورو قومونو په شان ژوند تېر کړُو، څوک چې د لرګو او د کاڼو د بُتانو عبادت کوى. خو ستاسو په ذهن کښې چې څۀ دى هغه به کله هم پوره نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19813, 'Ezekiel 20:33', 'Ezekiel', 20, 33, '&nbsp;”زما دې په خپل ذات قسم وى مالِک قادر مطلق خُدائ فرمائى، زۀ به په مضبوطو لاسونو سره په تاسو حکومت وکړم او خپل لاس به دراوږد کړم او خپل غضب به په تاسو نازل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19814, 'Ezekiel 20:34', 'Ezekiel', 20, 34, '&nbsp;زۀ به په خپل زورَور او غزېدلى لاس او راپارېدلى غضب سره تاسو د هغه مُلکونو نه واپس راولم کومو ته چې تاسو خوارۀ وارۀ شوى وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19815, 'Ezekiel 20:35', 'Ezekiel', 20, 35, '&nbsp;زۀ به تاسو د قومونو بيابان ته راولم او هلته به زۀ تاسو سره مخامخ شم او ستاسو عدالت به وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19816, 'Ezekiel 20:36', 'Ezekiel', 20, 36, '&nbsp;لکه څنګه چې ما ستاسو د پلار نيکۀ د مِصر په بيابان کښې عدالت کړے وو، نو هم هغه شان به زۀ ستاسو عدالت وکړم، مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19817, 'Ezekiel 20:37', 'Ezekiel', 20, 37, '&nbsp;چې زۀ به ستاسو سره حساب کوم چې تاسو خپل لوظ پوره کړے دے کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19818, 'Ezekiel 20:38', 'Ezekiel', 20, 38, '&nbsp;زۀ به تاسو د هغه خلقو نه راچاڼ کړم څوک چې زما خلاف ګناه او سرکشى کوى. اګر کۀ زۀ به هغوئ د هغه مُلک نه راوباسم چرته چې هغوئ اوسيږى خو هغوئ به د بنى اِسرائيلو په مُلک کښې داخل نۀ شى. بيا به تاسو پوهه شئ چې زۀ مالِک خُدائ يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19819, 'Ezekiel 20:39', 'Ezekiel', 20, 39, '&nbsp;تر څو پورې چې ستاسو خبره ده اے د بنى اِسرائيلو قومه، مالِک قادر مطلق خُدائ داسې فرمائى، تاسو ټول لاړ شئ او د خپلو بُتانو عبادت وکړئ، خو د دې نه وروستو به تاسو په يقين سره ما ته غوږ ونيسئ او په خپلو نذرانو او د بُتانو په وجه به نور زما د مقدس نوم سپکاوے نۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19820, 'Ezekiel 20:40', 'Ezekiel', 20, 40, '&nbsp;زما په مقدس غر، د بنى اِسرائيلو په اوچت غر، مالِک قادر مطلق خُدائ فرمائى، هلته په هغه مُلک کښې د بنى اِسرائيلو ټول قوم به زما عبادت وکړى، او هلته به زۀ هغوئ قبول کړم. او هلته به زۀ ستاسو نه نذرانې او غوره تحفې او ستاسو ټولې مقدسې قربانۍ وغواړمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19821, 'Ezekiel 20:41', 'Ezekiel', 20, 41, '&nbsp;زۀ چې کله تاسو د هغه مُلکونو نه واپس راولم او د هغه مُلکونو نه مو راغونډ کړم کومو ته چې تاسو خوارۀ وارۀ شوې وئ، نو زۀ به تاسو د ښکلې خوشبو په شان قبول کړم، او زۀ به خپل ځان ستاسو په مينځ کښې او د نورو قومونو په نظر کښې مقدس څرګند کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19822, 'Ezekiel 20:42', 'Ezekiel', 20, 42, '&nbsp;نو تاسو به پوهه شئ چې زۀ مالِک خُدائ يم کله چې زۀ تاسو د بنى اِسرائيلو مُلک ته واپس راولم، هغه مُلک ته چې ما په اوچتو لاسونو ستاسو پلار نيکۀ ته د ورکولو قسم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19823, 'Ezekiel 20:43', 'Ezekiel', 20, 43, '&nbsp;نو هلته به تاسو ته خپل ټول چال چلن او عملونه درياد شى د کومو په کولو چې تاسو خپل ځان پليت کړے دے، او د خپل ځان نه به نفرت کوئ د هغه اعمالو په وجه کوم چې تاسو کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19824, 'Ezekiel 20:44', 'Ezekiel', 20, 44, '&nbsp;تاسو به په دې پوهه شئ ‎چې زۀ مالِک خُدائ يم، اے د بنى اِسرائيلو قومه، کله چې زۀ تاسو سره د خپل نوم د خاطره نرم سلوک وکړم او ستاسو د خرابو کارونو او ستاسو د غلطو اعمالو په مطابق سلوک ونۀ کړم، مالِک قادر مطلق خُدائ دا فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19825, 'Ezekiel 20:45', 'Ezekiel', 20, 45, '&nbsp;نو بيا د مالِک خُدائ کلام په ما نازل شو چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19826, 'Ezekiel 20:46', 'Ezekiel', 20, 46, '&nbsp;”اے بنى آدمه، د جنوب خوا ته وګوره، د جنوب خلاف تبليغ وکړه او د جنوبى مُلک د ځنګلو په خلاف پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19827, 'Ezekiel 20:47', 'Ezekiel', 20, 47, '&nbsp;جنوبى ځنګل ته ووايه، د مالِک خُدائ کلام واورئ، مالِک قادر مطلق خُدائ داسې فرمائى، زۀ اوس په تاسو باندې اور لګوم، او دا به ستا ټولې شنې او وچې ونې وسوزوى. دا د اور لمبې به مړې نۀ شى، او د جنوب نه د شمال پورې ټول مخونه به د دې په لمبو وسوزى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19828, 'Ezekiel 20:48', 'Ezekiel', 20, 48, '&nbsp;هر يو به يې وګورى چې ما مالِک خُدائ دا اور لګولے دے، دا به مړ نۀ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19829, 'Ezekiel 20:49', 'Ezekiel', 20, 49, '&nbsp;بيا ما وفرمائيل چې، ”اے مالِکه قادر مطلق خُدايه، هغوئ زما په حقله وائى چې، ولې هغه هسې متلونه نۀ وائى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19830, 'Ezekiel 21:1', 'Ezekiel', 21, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19831, 'Ezekiel 21:2', 'Ezekiel', 21, 2, '&nbsp;”اے بنى آدمه، د يروشلم په خلاف خپل مخ راواړوه او د هغوئ د مقدسو ځايونو خلاف بيان وکړه. او د بنى اِسرائيلو د مُلک خلاف پېشګوئې وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19832, 'Ezekiel 21:3', 'Ezekiel', 21, 3, '&nbsp;او هغوئ ته ووايه چې مالِک خُدائ فرمائى، زۀ ستاسو خلاف يم. زۀ به خپله تُوره د کاش نه راوباسم او ستاسو نه به صادقان او بدعمله دواړه ختم کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19833, 'Ezekiel 21:4', 'Ezekiel', 21, 4, '&nbsp;ځکه زۀ صادقان او ګناهګاران دواړه وژنم، زما تُوره به د کاش نه د جنوب نه د شمال پورې د هر چا خلاف راوويستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19834, 'Ezekiel 21:5', 'Ezekiel', 21, 5, '&nbsp;بيا به ټول خلق په دې باندې پوهه شى چې ما مالِک خُدائ خپله تُوره د کاش نه راويستې ده. دا به بيا واپس نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19835, 'Ezekiel 21:6', 'Ezekiel', 21, 6, '&nbsp;نو په دې وجه اے بنى آدمه، زبيرګى کوه، په مات زړۀ او سختو دردونو سره د هغوئ په وړاندې سوال زارى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19836, 'Ezekiel 21:7', 'Ezekiel', 21, 7, '&nbsp;او کله چې هغوئ تا نه تپوس وکړى چې تۀ ولې زبيرګى کوې؟ نو هغوئ ته ووايه چې د هغه خبر په وجه چې راتلونکے دے. هر يو سخت زړۀ به نرم شى او هر يو لاس به شل شى، هر يو روح به ودريږى او هره يوه ګوډه به د يرې نه په ريږدان شى. دا راتلونکى دى، دا به په يقين سره وشى، مالِک قادر مطلق خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19837, 'Ezekiel 21:8', 'Ezekiel', 21, 8, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19838, 'Ezekiel 21:9', 'Ezekiel', 21, 9, '&nbsp;”اے بنى آدمه، پېشګوئې وکړه او خلقو ته ووايه، مالِک خُدائ داسې فرمائى چې، يوه تُوره تيره شوې او پالش شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19839, 'Ezekiel 21:10', 'Ezekiel', 21, 10, '&nbsp;دا د قتل و غارت دپاره تيره شوې ده، داسې پالش شوه چې د برېښنا په شان ځليږى. نو آيا اوس به خوشحاله شې څۀ؟ هغوئ څوک چې ستاسو نه ډېر زيات زورَور وُو د دې تُورې لاندې راغلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19840, 'Ezekiel 21:11', 'Ezekiel', 21, 11, '&nbsp;ما تُوره چا له ورکړې ده چې تيره يې کړى. اوس دا تيره ده، چمکداره ده او تياره ده چې قاتل ترېنه کار واخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19841, 'Ezekiel 21:12', 'Ezekiel', 21, 12, '&nbsp;اے بنى آدمه، وير او ژړا وکړه، ځکه دا زما د خلقو خلاف ده، دا د بنى اِسرائيلو د ټولو شهزادګانو خلاف ده. هغوئ زما خلقو سره يوځائ د تُورې خولې ته وغورزولے شول. نو په دې وجه خپلې سينې ووهئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19842, 'Ezekiel 21:13', 'Ezekiel', 21, 13, '&nbsp;دا به هغوئ ټول په آزمېښت کښې واچوى، نو دوئ سره به د خلاصون لار نۀ وى؟“ مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19843, 'Ezekiel 21:14', 'Ezekiel', 21, 14, '&nbsp;”نو بيا اے بنى آدمه، نبوت وکړه او خپل لاسونه وپړقوه او زما تُوره به دوه ځله بلکې درې ځله ووهى. دا تُوره د تباهۍ دپاره ده او دا تُوره د لوئ قتل و غارت دپاره ده چې د هرې خوا نه به هغوئ راګېر کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19844, 'Ezekiel 21:15', 'Ezekiel', 21, 15, '&nbsp;تر دې چې هغوئ د يرې نه خپل زړونه بائيلى او راوغورزيږى، ما د هغوئ په ټولو دروازو کښې تُوره د دوئ د وژلو دپاره مقرر کړې ده. افسوس، هغه داسې جوړه شوې ده چې لکه د برېښنا په شان پړقيږى، او دا د قتلولو دپاره راخستلے شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19845, 'Ezekiel 21:16', 'Ezekiel', 21, 16, '&nbsp;اے تُورې، ښى طرف او بيا ګس طرف ته، او هرې خوا چې ستا مخ تاويږى وڅيره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19846, 'Ezekiel 21:17', 'Ezekiel', 21, 17, '&nbsp;زۀ به هم خپل لاسونه وپړقوم او زما غضب به سوړ شى. ما مالِک خُدائ داسې وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
