(19880, 'Ezekiel 22:19', 'Ezekiel', 22, 19, '&nbsp;نو په دې وجه مالِک قادر مطلق خُدائ داسې فرمائى، ځکه چې تاسو ټولو نه پاتې شوے ګند جوړ شوے دے، نو زۀ به تاسو يروشلم ته راټول کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19881, 'Ezekiel 22:20', 'Ezekiel', 22, 20, '&nbsp;لکه څنګه چې خلق سپين زر، تانبه، اوسپنه، سيکه او ټيمان راټولوى او په بټۍ کښې يې په تېز اور ويلى کوى، نو هم داسې به زۀ تاسو خپل قهر او غضب کښې راټول کړم او په ښار کښې دننه به مو واچوم او ويلى به مو کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19882, 'Ezekiel 22:21', 'Ezekiel', 22, 21, '&nbsp;زۀ به تاسو راټول کړم او زۀ به خپل يروونکے غضب په تاسو نازل کړم، او تاسو به په هغې کښې دننه ويلى شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19883, 'Ezekiel 22:22', 'Ezekiel', 22, 22, '&nbsp;لکه څنګه چې سپين زر په بټۍ کښې ويلى کيږى، نو دغه شان به تاسو په هغې کښې دننه ويلى شئ، او تاسو به پوهه شئ چې ما، مالِک خُدائ په تاسو خپل قهر او غضب نازل کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19884, 'Ezekiel 22:23', 'Ezekiel', 22, 23, '&nbsp;بيا د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19885, 'Ezekiel 22:24', 'Ezekiel', 22, 24, '&nbsp;”اے بنى آدمه، دې مُلک ته ووايه چې، تۀ هغه مُلک يې چې لا پاک شوے نۀ يې، په تا د غضب په ورځو کښې باران ونۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19886, 'Ezekiel 22:25', 'Ezekiel', 22, 25, '&nbsp;د هغۀ سازش کوونکى شهزادګان د هغه غړمبېدونکو زمرو په شان دى چې خپل ښکار په مينځ شلوى، هغوئ انسانان خورى، هغوئ مال دولت او قيمتى څيزونه چور کوى او د دې ډيرې ښځې کونډې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19887, 'Ezekiel 22:26', 'Ezekiel', 22, 26, '&nbsp;د هغۀ اِمامان زما شريعت ماتوى او زما د مقدسو څيزونو بې‌حرمتى کوى، هغوئ د مقدسو څيزونو او د عامو څيزونو په مينځ کښې فرق نۀ کوى، او هغوئ د پاکو او پليتو په مينځ کښې د فرق کولو تعليم نۀ ورکوى، او هغوئ زما د سبت په ساتلو باندې خپلې سترګې پټوى، نو زۀ د هغوئ په مينځ کښې سپک شوے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19888, 'Ezekiel 22:27', 'Ezekiel', 22, 27, '&nbsp;د هغۀ سرکارى آفسران لکه د ليوانو په شان خپل ښکار شلوى، هغوئ وينه تويوى او خلق وژنى چې بې‌اِنصافه ګټه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19889, 'Ezekiel 22:28', 'Ezekiel', 22, 28, '&nbsp;د هغې نبيان په غلطو روياګانو او دروغژنو پېشګويو سره د هغوئ دا کارونه صفا کوى. هغوئ وائى چې، دا مالِک قادر مطلق خُدائ فرمائى، خو په حقيقت کښې مالِک خُدائ دا نۀ وى فرمائيلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19890, 'Ezekiel 22:29', 'Ezekiel', 22, 29, '&nbsp;د هغه مُلک خلق زياتے کوى او غلا کوى، هغوئ په غريبانانو او محتاجو خلقو ظلم کوى، او د مسافرو سره بد سلوک کوى او د هغوئ حق نه اِنکار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19891, 'Ezekiel 22:30', 'Ezekiel', 22, 30, '&nbsp;ما د هغوئ په مينځ کښې د يو داسې کس لټون کولو چې د دېوال مرمت وکړى او په وران شوى ځائ لکه د دېوال په شان ودريږى د هغه مُلک دپاره ودريږى چې زۀ يې تباه نۀ کړم، خو ما څوک هم پېدا نۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19892, 'Ezekiel 22:31', 'Ezekiel', 22, 31, '&nbsp;نو زۀ به په هغوئ خپل غضب رانازل کړم او هغوئ به په خپل سخت قهر کښې وسوزوم، او هر هغه څۀ به د هغوئ په خپل سر راولم څۀ چې هغوئ کړى دى. مالِک قادر مطلق خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19893, 'Ezekiel 23:1', 'Ezekiel', 23, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19894, 'Ezekiel 23:2', 'Ezekiel', 23, 2, '&nbsp;”اے بنى آدمه، دوه ښځې وې چې د يوې مور لوڼه وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19895, 'Ezekiel 23:3', 'Ezekiel', 23, 3, '&nbsp;هغوئ په مِصر کښې کنجرې جوړې شوې، او په پېغلتوب کښې يې پردو سړو ته د خپلو سينو سره د لوبو کولو اجازت ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19896, 'Ezekiel 23:4', 'Ezekiel', 23, 4, '&nbsp;د مشرې نامه اوحوله وه، او د هغې د خور نامه اوحوليبه وه. هغوئ زما وې او زامن او لوڼه يې راوړل. د اوحوله نه سامريه مطلب دے، او اوحوليبه نه يروشلم مطلب دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19897, 'Ezekiel 23:5', 'Ezekiel', 23, 5, '&nbsp;اوحوله په کنجرتوب کښې آخته شوه کله چې هغه لا زما وه، او هغه د شوق نه خپلو عاشقانو د اسورى جنګيالو پسې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19898, 'Ezekiel 23:6', 'Ezekiel', 23, 6, '&nbsp;سرکارى آفسران او کمانډران ټول ښکلى ځوانان وُو او شاندراې جامې يې اچولې وې او په آسونو سوارۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19899, 'Ezekiel 23:7', 'Ezekiel', 23, 7, '&nbsp;هغې خپل ځان د اسوريانو ټولو آفسرانو ته لکه د کنجرې په شان پېش کړو او خپل ځان يې د هغه هر چا ټولو بُتانو سره پليت کړو چا پسې چې د هغې شوق وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(19900, 'Ezekiel 23:8', 'Ezekiel', 23, 8, '&nbsp;هغې هغه کنجرتوب پرې نۀ ښودو چې په مِصر کښې يې شروع کړے وو، کله چې د هغې د پېغلتوب په دوران کښې سړى د هغې سره څملاستل او د هغې سينو سره يې لوبې وکړې او خپل شوق يې په هغې پوره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');